#!/data/data/com.termux/files/usr/bin/bash
# ============================================================================
# Install and configure code-server (VS Code in the browser) on Termux, with Claude Code support
# Generated by tpf from src/code-server/ - do not edit, run ./tpf build.
# code-server 3.5 (sources sha256:a608545d5f70f9ea)
# ============================================================================
# shellcheck disable=SC2034  # available to the script, not always used
TPF_NAME=code-server
TPF_VERSION=3.5
TPF_SOURCE_HASH=a608545d5f70f9ea
#
# install-code-server-termux.sh — v3.4 (--claude-code: binary wrapped in place)
# ============================================================================
# Installs, or cleanly reinstalls, code-server on Termux (Android).
#
# How it works
#   Every run replaces the code-server installation, so the script can be
#   run as many times as needed:
#     1. any running code-server is stopped;
#     2. every known installation is removed (apt/TUR package, global npm
#        package, standalone ~/.local/lib/code-server-*, legacy yarn global);
#     3. code-server is installed again;
#     4. the result is checked by actually running `code-server --version`;
#     5. in "auto" mode, if the first method gives a broken install, the
#        other method is tried.
#
#   A single management script is then installed:
#       ~/code-server.sh  start | stop | restart | status | log
#   It reads its settings from ~/code-server.conf (port, address,
#   authentication, start-up timeout and retries, ...).
#
#   User data (editor settings, extensions, launcher settings) is kept.
#   Use --purge-data to reset it as well.
#
# References (official code-server documentation)
#   https://coder.com/docs/code-server/termux
#       Termux install through the TUR repository, build dependencies for
#       npm installs, the "Android as Linux" workaround, keyboard settings.
#   https://coder.com/docs/code-server/npm
#       npm install requirements: the Node.js major version must be the one
#       code-server expects; yarn is not supported.
#   https://coder.com/docs/code-server/FAQ
#       Choosing another extension marketplace ($EXTENSIONS_GALLERY).
#
# Run `bash install-code-server-termux.sh --help` for the list of options.
# ============================================================================

# `set -e` is deliberately NOT used: every step checks its own result so the
# script can explain what went wrong and try alternatives.
set -uo pipefail

# --- tpf: begin src/lib/core.sh ---
# Basics shared by every installer: checks, clean exit, signals, wake lock.
#
# Commands: have is_uint is_port require_termux require_aarch64
#           on_exit wake_lock
# --- tpf: begin src/lib/ui.sh ---
# Output style shared by every installer (see docs/STYLE.md).
#
#   [INFO] [ OK ] [ ?? ] [WARN]    six columns: the text always starts at column 8
#   [ERROR]                        danger: seven columns, written to stderr
#   [.   ] [..  ] [... ] ...       a task that is running (see task)
#
# Commands: info ok warn err detail step banner die
#           ask_yes_no ask_input ask_choice task
# Variable: TPF_ASSUME=yes|no answers every question without asking.

_UI_FRAMES=('[.   ]' '[..  ]' '[... ]' '[ ...]' '[  ..]' '[   .]')
_UI_CURSOR_HIDDEN=0
_TASK_PID=""

# ui_colors on|off|auto
ui_colors() {
    local mode="${1:-auto}"
    if [ "$mode" = auto ]; then
        if [ -t 1 ] && [ -z "${NO_COLOR:-}" ] && [ "${TERM:-}" != dumb ]; then mode=on; else mode=off; fi
    fi
    if [ "$mode" = on ]; then
        C_RESET=$'\033[0m'; C_BOLD=$'\033[1m'; C_DIM=$'\033[2m'
        C_INFO=$'\033[1;34m'; C_OK=$'\033[1;32m'; C_WARN=$'\033[1;33m'
        C_ERR=$'\033[1;31m'; C_ASK=$'\033[1;36m'
    else
        C_RESET=""; C_BOLD=""; C_DIM=""
        C_INFO=""; C_OK=""; C_WARN=""; C_ERR=""; C_ASK=""
    fi
}
ui_colors auto

# True when a running task can be animated in place.
_ui_animated() {
    [ -t 1 ] && [ "${TERM:-}" != dumb ] && [ -z "${TPF_NO_ANIM:-}" ]
}

# Everything printed is also appended, without colours, to $TPF_LOG_DIR/run.log.
_ui_log() {
    [ -n "${TPF_LOG_DIR:-}" ] && [ -d "${TPF_LOG_DIR}" ] || return 0
    printf '%s %-5s %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$1" "$2" >>"$TPF_LOG_DIR/run.log" 2>/dev/null || true
}

_ui_line() {   # colour tag text
    printf '%s%s%s %s\n' "$1" "$2" "$C_RESET" "$3"
}

info() { _ui_line "$C_INFO" '[INFO]' "$*"; _ui_log INFO "$*"; }
ok()   { _ui_line "$C_OK" '[ OK ]' "$*"; _ui_log OK "$*"; }
warn() { _ui_line "$C_WARN" '[WARN]' "$*"; _ui_log WARN "$*"; }
err()  { _ui_line "$C_ERR" '[ERROR]' "$*" >&2; _ui_log ERROR "$*"; }

# A dimmed line aligned with the text of the lines above.
detail() { printf '       %s%s%s\n' "$C_DIM" "$*" "$C_RESET"; }

step() {
    printf '\n%s=== %s ===%s\n' "$C_INFO" "$*" "$C_RESET"
    _ui_log STEP "$*"
}

# banner TITLE [SUBTITLE]
banner() {
    local bar="============================================================"
    printf '\n%s%s\n %s\n' "$C_OK" "$bar" "$1"
    [ -z "${2:-}" ] || printf ' %s\n' "$2"
    printf '%s%s\n' "$bar" "$C_RESET"
}

die() {
    err "$*"
    if [ -n "${TPF_LOG_DIR:-}" ] && [ -d "${TPF_LOG_DIR}" ]; then
        printf '       %sLogs: %s%s\n' "$C_DIM" "$TPF_LOG_DIR" "$C_RESET" >&2
    fi
    exit 1
}

# ---------------------------------------------------------------------------
# Questions. They read /dev/tty, so they also work with `curl ... | bash`.
# The answer of ask_input / ask_choice is left in $ANSWER.
# ---------------------------------------------------------------------------
_ui_have_tty() { ( : </dev/tty ) 2>/dev/null; }

_ui_prompt() {   # text; reads one line from the terminal into $_UI_REPLY
    _UI_REPLY=""
    printf '%s[ ?? ]%s %s' "$C_ASK" "$C_RESET" "$1" >/dev/tty
    IFS= read -r _UI_REPLY </dev/tty || _UI_REPLY=""
}

# ask_yes_no "question" [yes|no]   -> status 0 for yes
ask_yes_no() {
    local question="$1" def="${2:-no}" hint
    case "${TPF_ASSUME:-}" in
        yes) _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: yes]${C_RESET}"; return 0 ;;
        no)  _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: no]${C_RESET}"; return 1 ;;
    esac
    if [ "$def" = yes ]; then hint="[Y/n]"; else hint="[y/N]"; fi
    if _ui_have_tty; then
        _ui_prompt "$question $hint "
        case "$_UI_REPLY" in
            y|Y|yes|Yes|YES|o|O|oui|Oui|OUI) return 0 ;;
            n|N|no|No|NO|non|Non|NON) return 1 ;;
            *) [ "$def" = yes ]; return ;;
        esac
    fi
    warn "No terminal available: default answer \"$def\" used ($question)"
    [ "$def" = yes ]
}

# ask_input "question" "default"   -> $ANSWER
ask_input() {
    local question="$1" def="${2:-}"
    ANSWER="$def"
    if [ -n "${TPF_ASSUME:-}" ]; then
        _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: ${def:-empty}]${C_RESET}"
        return 0
    fi
    if _ui_have_tty; then
        _ui_prompt "$question${def:+ [$def]} "
        [ -z "$_UI_REPLY" ] || ANSWER="$_UI_REPLY"
        return 0
    fi
    warn "No terminal available: default \"${def:-empty}\" used ($question)"
}

# ask_choice "question" DEFAULT option...   -> $ANSWER (one of the options)
ask_choice() {
    local question="$1" def="$2" opt n=0
    shift 2
    ANSWER="$def"
    if [ -n "${TPF_ASSUME:-}" ] || ! _ui_have_tty; then
        _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: $def]${C_RESET}"
        return 0
    fi
    _ui_line "$C_ASK" '[ ?? ]' "$question"
    for opt in "$@"; do
        n=$((n + 1))
        printf '       %s%d)%s %s%s\n' "$C_BOLD" "$n" "$C_RESET" "$opt" "$([ "$opt" = "$def" ] && printf ' (default)')"
    done
    _ui_prompt "Choice [1-$n or name] "
    n=0
    for opt in "$@"; do
        n=$((n + 1))
        if [ "$_UI_REPLY" = "$n" ] || [ "$_UI_REPLY" = "$opt" ]; then ANSWER="$opt"; return 0; fi
    done
    [ -z "$_UI_REPLY" ] || warn "\"$_UI_REPLY\" is not an option: default \"$def\" used"
}

# ---------------------------------------------------------------------------
# task "message" command [args...]
#
# Runs the command with its output sent to a log file and shows an animated
# [.   ] [..  ] [... ] marker while it runs, then replaces it by [ OK ] or
# [ERROR]. Returns the status of the command; on failure the last lines of the
# log are shown. The command runs in a subshell: variables it sets are lost.
# ---------------------------------------------------------------------------
_ui_cleanup() {
    if [ "$_UI_CURSOR_HIDDEN" = 1 ]; then printf '\033[?25h'; _UI_CURSOR_HIDDEN=0; fi
}

_task_logfile() {
    local slug
    slug="$(printf '%s' "$1" | tr -c 'A-Za-z0-9' '-' | tr -s '-' | sed 's/^-//; s/-$//' | cut -c1-48)"
    printf '%s/%s.log' "${TPF_LOG_DIR:-${TMPDIR:-/tmp}}" "${slug:-task}"
}

task() {
    local msg="$1" log rc=0 i=0 started=$SECONDS took=""
    shift
    [ -z "${TPF_LOG_DIR:-}" ] || mkdir -p "$TPF_LOG_DIR" 2>/dev/null || true
    log="$(_task_logfile "$msg")"
    if _ui_animated; then
        "$@" >"$log" 2>&1 </dev/null &
        _TASK_PID=$!
        printf '\033[?25l'; _UI_CURSOR_HIDDEN=1
        while kill -0 "$_TASK_PID" 2>/dev/null; do
            printf '\r\033[K%s%s%s %s' "$C_INFO" "${_UI_FRAMES[i % ${#_UI_FRAMES[@]}]}" "$C_RESET" "$msg"
            i=$((i + 1))
            sleep 0.15
        done
        wait "$_TASK_PID"; rc=$?
        _TASK_PID=""
        printf '\r\033[K'
        _ui_cleanup
    else
        _ui_line "$C_INFO" '[ .. ]' "$msg"
        "$@" >"$log" 2>&1 </dev/null; rc=$?
    fi
    [ $((SECONDS - started)) -lt 2 ] || took=" ${C_DIM}($((SECONDS - started))s)${C_RESET}"
    if [ "$rc" -eq 0 ]; then
        _ui_line "$C_OK" '[ OK ]' "$msg$took"
        _ui_log OK "$msg"
    else
        _ui_line "$C_ERR" '[ERROR]' "$msg (exit $rc)$took" >&2
        _ui_log ERROR "$msg (exit $rc)"
        if [ -s "$log" ]; then
            tail -n 8 "$log" | sed "s/^/       ${C_DIM}/; s/\$/${C_RESET}/" >&2
            printf '       %sFull log: %s%s\n' "$C_DIM" "$log" "$C_RESET" >&2
        fi
    fi
    return "$rc"
}
# --- tpf: end src/lib/ui.sh ---

have()    { command -v "$1" >/dev/null 2>&1; }
is_uint() { case "${1:-}" in '' | *[!0-9]*) return 1 ;; esac; }
is_port() { is_uint "${1:-}" && [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; }

require_termux() {
    case "${PREFIX:-}" in
        *com.termux*) ;;
        *) die "This script must be run inside Termux." ;;
    esac
    [ -n "${HOME:-}" ] || die "\$HOME is not set."
}

require_aarch64() {
    case "$(uname -m)" in
        aarch64 | arm64) ;;
        *) die "Only 64-bit ARM (aarch64) is supported (this device: $(uname -m))." ;;
    esac
}

# ---------------------------------------------------------------------------
# Clean exit. Register cleanup commands with on_exit; they run in reverse
# order when the script ends, whatever the reason (end, die, Ctrl-C).
# ---------------------------------------------------------------------------
_TPF_EXIT_CMDS=()

on_exit() { _TPF_EXIT_CMDS+=("$1"); }

_tpf_exit() {
    local status=$? i
    trap - EXIT
    if [ -n "${_TASK_PID:-}" ]; then kill "$_TASK_PID" 2>/dev/null || true; fi
    _ui_cleanup
    for ((i = ${#_TPF_EXIT_CMDS[@]} - 1; i >= 0; i--)); do
        eval "${_TPF_EXIT_CMDS[i]}" || true
    done
    exit "$status"
}

_tpf_signal() {   # name status
    printf '\n' >&2
    err "Interrupted ($1)."
    exit "$2"
}

trap _tpf_exit EXIT
trap '_tpf_signal INT 130' INT
trap '_tpf_signal TERM 143' TERM

# wake_lock: keep Android from suspending Termux until the script ends.
_TPF_WAKE=0
wake_lock() {
    [ "$_TPF_WAKE" = 0 ] || return 0
    if have termux-wake-lock && termux-wake-lock >/dev/null 2>&1; then
        _TPF_WAKE=1
        on_exit 'termux-wake-unlock >/dev/null 2>&1'
    fi
    return 0
}
# --- tpf: end src/lib/core.sh ---
# --- tpf: begin src/lib/args.sh ---
# Command line options common to every installer.
#
#   -y, --yes   -n, --no   --no-color   --log-dir DIR   -V, --version   -h, --help
#
# In the option loop of a script:
#
#   while [ $# -gt 0 ]; do
#       case "$1" in
#           --my-option) MY=1 ;;
#           *) std_opt "$@" || die "Unknown option: $1 (try --help)"; shift "$STD_SHIFT"; continue ;;
#       esac
#       shift
#   done
#
# The script defines usage() and may print std_usage inside it.

STD_SHIFT=1
TPF_ASSUME="${TPF_ASSUME:-}"

# need_value OPTION ARGC   -> dies when an option that takes a value has none
need_value() {
    [ "$2" -ge 2 ] || die "Option $1 needs a value (try --help)"
}

std_usage() {
    cat <<'USAGE'
  -y, --yes        Answer "yes" to every question
  -n, --no         Answer "no" to every question
      --no-color   Plain output without colours
      --log-dir D  Write the logs to D
  -V, --version    Print the version and exit
  -h, --help       Show this help
USAGE
}

# std_opt "$@": handles the first argument if it is a common option.
# Returns 1 when it is not one. Sets STD_SHIFT to the number of arguments used.
std_opt() {
    STD_SHIFT=1
    case "$1" in
        -y | --yes) TPF_ASSUME=yes ;;
        -n | --no) TPF_ASSUME=no ;;
        --no-color) ui_colors off ;;
        --log-dir)
            need_value "$1" $#
            TPF_LOG_DIR="$2"
            STD_SHIFT=2
            ;;
        --log-dir=*) TPF_LOG_DIR="${1#*=}" ;;
        -V | --version)
            printf '%s %s\n' "$TPF_NAME" "$TPF_VERSION"
            exit 0
            ;;
        -h | --help)
            if declare -F usage >/dev/null; then usage; else printf 'Usage: %s [options]\n' "$TPF_NAME"; fi
            exit 0
            ;;
        *) return 1 ;;
    esac
}
# --- tpf: end src/lib/args.sh ---
# --- tpf: begin src/lib/log.sh ---
# Log directory of a script. Everything printed by info/ok/warn/err/step is also
# recorded (without colours) in $TPF_LOG_DIR/run.log; task output goes to one file
# per task in the same directory.
#
# Command: log_init [DIR]   (default: ~/.cache/tpf/$TPF_NAME, or --log-dir)

log_init() {
    TPF_LOG_DIR="${TPF_LOG_DIR:-${1:-$HOME/.cache/tpf/$TPF_NAME}}"
    mkdir -p "$TPF_LOG_DIR" 2>/dev/null || { warn "Cannot create the log directory $TPF_LOG_DIR"; TPF_LOG_DIR=""; return 0; }
    export TPF_LOG_DIR
}
# --- tpf: end src/lib/log.sh ---

# ---------------------------------------------------------------------------
# Options
# ---------------------------------------------------------------------------
usage() {
    cat <<'EOF'
Usage: bash install-code-server-termux.sh [options]

Options:
  -y, --yes          Answer "yes" to every optional question
  -n, --no           Answer "no" to every optional question
  --method M         auto (default) | tur | npm
  --port N           Listening port (default: saved value, else 8080)
  --bind ADDR        Listening address (default: saved value, else 127.0.0.1)
                     0.0.0.0 = reachable from other devices on the network
  --auth MODE        none | password (default: saved value, else none)
  --new-password     Generate a new password (with --auth password)
  --purge-data       Also delete editor settings, extensions and user data
  --no-reset         Keep the existing install if it works (soft repair)
  --skip-update      Skip `apt update` / `apt upgrade` (faster)
  --claude-code      Make the Claude Code extension work (glibc loader +
                     launcher script replacing its binary). Implies the
                     "Android as Linux" workaround.
  --no-claude-code   Do not set it up (and remove the wrapper setting)
  --uninstall        Remove everything and exit
  -h, --help         Show this help

Without --yes / --no, each question defaults to the choice saved by the
previous run, or to "no" on a first install. When no terminal is available
(for example when the script is piped from curl), the defaults are used.

Common options:
EOF
    std_usage
    exit 0
}

METHOD="auto"
PORT=""                # empty = keep the saved value (or the default)
BIND_HOST=""
AUTH_MODE=""
DO_RESET=1
PURGE_DATA=0
NEW_PASSWORD=0
SKIP_UPDATE=0
UNINSTALL_ONLY=0
CLAUDE_OPT=""          # "" = ask / saved value | 1 | 0

while [ $# -gt 0 ]; do
    case "$1" in
        --method)        need_value "$1" $#; METHOD="$2"; shift ;;
        --method=*)      METHOD="${1#*=}" ;;
        --port)          need_value "$1" $#; PORT="$2"; shift ;;
        --port=*)        PORT="${1#*=}" ;;
        --bind)          need_value "$1" $#; BIND_HOST="$2"; shift ;;
        --bind=*)        BIND_HOST="${1#*=}" ;;
        --auth)          need_value "$1" $#; AUTH_MODE="$2"; shift ;;
        --auth=*)        AUTH_MODE="${1#*=}" ;;
        --new-password)  NEW_PASSWORD=1 ;;
        --purge-data)    PURGE_DATA=1 ;;
        --no-reset)      DO_RESET=0 ;;
        --skip-update)   SKIP_UPDATE=1 ;;
        --uninstall)     UNINSTALL_ONLY=1 ;;
        --claude-code)   CLAUDE_OPT=1 ;;
        --no-claude-code) CLAUDE_OPT=0 ;;
        *)               std_opt "$@" || die "Unknown option: $1 (try --help)"; shift "$STD_SHIFT"; continue ;;
    esac
    shift
done

case "$METHOD" in auto|tur|npm) ;; *) die "--method must be auto, tur or npm (got: $METHOD)" ;; esac
case "$AUTH_MODE" in ''|none|password) ;; *) die "--auth must be none or password (got: $AUTH_MODE)" ;; esac
[ -z "$PORT" ] || is_port "$PORT" || die "--port must be a number between 1 and 65535 (got: $PORT)"
case "$BIND_HOST" in
    *:*|*[[:space:]]*|*\"*|*\'*) die "--bind must be an IPv4 address or a host name (got: $BIND_HOST)" ;;
esac

# ---------------------------------------------------------------------------
# Environment checks and paths
# ---------------------------------------------------------------------------
require_termux

ARCH="$(uname -m)"

WRAPPER="$HOME/code-server.sh"
WRAPPER_CONF="$HOME/code-server.conf"
CONFIG_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/code-server"
DATA_DIR="${XDG_DATA_HOME:-$HOME/.local/share}/code-server"
SPOOF_FILE="$CONFIG_DIR/android-as-linux.js"
OLD_PREFS_FILE="$CONFIG_DIR/install-prefs.env"   # left by versions < 3.1
SETTINGS_FILE="$DATA_DIR/User/settings.json"
LOG_FILE="$HOME/.code-server.log"
PID_FILE="$HOME/.code-server.pid"
LOG_DIR="$HOME/.cache/code-server-install"
BOOT_FILE="$HOME/.termux/boot/50-code-server.sh"
CLAUDE_WRAPPER="$CONFIG_DIR/claude-code-wrapper.sh"        # old approach, only cleaned up
CLAUDE_WRAP_SCRIPT="$CONFIG_DIR/claude-wrap-binary.sh"

mkdir -p "$LOG_DIR" || die "Cannot create $LOG_DIR"
chmod 700 "$LOG_DIR" 2>/dev/null || true
log_init "$LOG_DIR"

CS_LOCATIONS=(
    "$PREFIX/lib/node_modules/code-server"
    "$HOME/.config/yarn/global/node_modules/code-server"
)

banner "code-server for Termux" "installer v$TPF_VERSION"
info "Architecture: $ARCH"
info "Termux PREFIX: $PREFIX"
if [ "$UNINSTALL_ONLY" = "1" ]; then
    info "Mode: full UNINSTALL"
elif [ "$DO_RESET" = "1" ]; then
    info "Mode: clean reinstall (the current install is removed, then reinstalled)"
else
    info "Mode: soft repair (--no-reset: a working install is kept)"
fi
[ "$PURGE_DATA" = "1" ] && warn "--purge-data: editor settings, extensions and user data will ALSO be deleted."

case "$ARCH" in
    aarch64|arm64) ;;
    armv7l|armv8l|arm) warn "32-bit architecture: the TUR package is often missing, npm fallback likely." ;;
    *) warn "Untested architecture ($ARCH): it may work, no guarantee." ;;
esac

# ---------------------------------------------------------------------------
# Process helpers
# ---------------------------------------------------------------------------
# Matches the real server only. A plain `pkill -f code-server` would also
# kill this script and code-server.sh, whose names contain "code-server".
CS_PROC_PATTERN='code-server([[:space:]]|$)|code-server/out/node/entry'

# True if $1 is a live code-server process (protects against reused PIDs
# from a stale PID file).
is_cs_pid() {
    local pid="${1:-}" cmd
    is_uint "$pid" || return 1
    [ -r "/proc/$pid/cmdline" ] || return 1
    cmd="$(tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null)"
    printf '%s\n' "$cmd" | grep -Eq "$CS_PROC_PATTERN"
}

cs_pids() {
    local pid
    for pid in $(pgrep -f "$CS_PROC_PATTERN" 2>/dev/null); do
        [ "$pid" = "$$" ] && continue
        [ "$pid" = "${PPID:-0}" ] && continue
        is_cs_pid "$pid" && echo "$pid"
    done
}

# A process and all its descendants (code-server starts child processes).
pid_tree() {
    local p
    echo "$1"
    for p in $(pgrep -P "$1" 2>/dev/null); do pid_tree "$p"; done
}

# Stops a process tree: SIGTERM, wait up to 5 s, then SIGKILL.
stop_pid() {
    local pids p i alive=""
    pids="$(pid_tree "$1")"
    # shellcheck disable=SC2086
    kill -TERM $pids 2>/dev/null
    for i in 1 2 3 4 5; do
        alive=""
        for p in $pids; do kill -0 "$p" 2>/dev/null && alive="$alive $p"; done
        [ -z "$alive" ] && return 0
        sleep 1
    done
    # shellcheck disable=SC2086
    kill -KILL $alive 2>/dev/null
    sleep 1
    for p in $alive; do kill -0 "$p" 2>/dev/null && return 1; done
    return 0
}

stop_running_instance() {
    local pid
    if [ -s "$PID_FILE" ]; then
        pid="$(cat "$PID_FILE" 2>/dev/null)"
        if is_cs_pid "$pid"; then
            info "Stopping code-server (PID $pid)..."
            stop_pid "$pid" || warn "PID $pid did not stop."
        fi
        rm -f "$PID_FILE"
    fi
    for pid in $(cs_pids); do
        info "Stopping leftover code-server process (PID $pid)..."
        stop_pid "$pid" || warn "PID $pid did not stop."
    done
    return 0
}

# ---------------------------------------------------------------------------
# code-server helpers
# ---------------------------------------------------------------------------
cs_install_root() {
    local bin real d
    bin="$(command -v code-server 2>/dev/null)" || return 1
    [ -n "$bin" ] || return 1
    real="$(readlink -f "$bin" 2>/dev/null || echo "$bin")"
    d="$(dirname "$real")"
    while [ "$d" != "/" ] && [ -n "$d" ]; do
        if [ -f "$d/package.json" ] && grep -q '"name"[[:space:]]*:[[:space:]]*"code-server"' "$d/package.json" 2>/dev/null; then
            echo "$d"; return 0
        fi
        d="$(dirname "$d")"
    done
    return 1
}

# Health check: this is what catches "Cannot find module ..." errors.
cs_health_check() {
    local out rc
    hash -r 2>/dev/null || true
    have code-server || { CS_HEALTH_MSG="no code-server binary in PATH"; return 1; }
    out="$(env -u NODE_OPTIONS timeout 180 code-server --version 2>&1)"; rc=$?
    printf '%s\n' "$out" > "$LOG_DIR/health.log"
    if [ $rc -ne 0 ]; then
        if printf '%s' "$out" | grep -q "MODULE_NOT_FOUND\|Cannot find module"; then
            CS_HEALTH_MSG="broken install (missing Node.js modules): $(printf '%s' "$out" | grep -m1 "Cannot find module")"
        elif [ $rc -eq 124 ]; then
            CS_HEALTH_MSG="'code-server --version' timed out"
        else
            CS_HEALTH_MSG="'code-server --version' failed (exit code $rc) — see $LOG_DIR/health.log"
        fi
        return 1
    fi
    CS_VERSION="$(printf '%s' "$out" | head -n1)"
    CS_HEALTH_MSG=""
    return 0
}

cs_supports_flag() {
    [ -n "${CS_HELP_CACHE:-}" ] || CS_HELP_CACHE="$(env -u NODE_OPTIONS timeout 120 code-server --help 2>&1)"
    printf '%s' "$CS_HELP_CACHE" | grep -q -- "$1"
}

gen_password() {
    # Hexadecimal only: safe in shell files, YAML and sed replacements.
    if have openssl; then
        openssl rand -hex 16
    else
        od -An -tx1 -N16 /dev/urandom | tr -d ' \n'
    fi
}

# Looks for a REAL su binary. Termux ships its own `su` wrapper in $PREFIX/bin
# that exists even on non-rooted devices, so `command -v su` is not proof of root.
find_real_su() {
    local c
    for c in /system/bin/su /system/xbin/su /sbin/su /su/bin/su /debug_ramdisk/su; do
        [ -x "$c" ] && { echo "$c"; return 0; }
    done
    return 1
}

# ---------------------------------------------------------------------------
# apt: repair an interrupted dpkg state + non-interactive options
# ---------------------------------------------------------------------------
export DEBIAN_FRONTEND=noninteractive
APT_OPTS=(-y -o Dpkg::Options::=--force-confdef -o Dpkg::Options::=--force-confold)

dpkg_installed() { dpkg-query -W -f='${Status}' "$1" 2>/dev/null | grep -q "ok installed"; }

apt_repair() {
    dpkg --configure -a >"$LOG_DIR/dpkg_configure.log" 2>&1 || true
    apt-get "${APT_OPTS[@]}" -f install >"$LOG_DIR/apt_fix.log" 2>&1 || true
}

# Installs packages quietly; repairs an interrupted dpkg state and retries once.
apt_install_quiet() {
    apt-get "${APT_OPTS[@]}" install "$@" >"$LOG_DIR/apt_extra.log" 2>&1 && return 0
    apt_repair
    apt-get "${APT_OPTS[@]}" install "$@" >"$LOG_DIR/apt_extra.log" 2>&1
}

# ---------------------------------------------------------------------------
# Removal
# ---------------------------------------------------------------------------
purge_code_server() {
    step "Removing existing installations"
    stop_running_instance

    if dpkg_installed code-server; then
        info "apt package 'code-server' found: purging..."
        apt-get "${APT_OPTS[@]}" purge code-server >"$LOG_DIR/apt_purge.log" 2>&1 \
            && ok "apt package removed." \
            || warn "apt purge failed (see $LOG_DIR/apt_purge.log), cleaning up manually."
        apt_repair
    fi

    if have npm; then
        if npm ls -g --depth=0 code-server >/dev/null 2>&1; then
            info "Global npm install found: uninstalling..."
            npm uninstall -g code-server >"$LOG_DIR/npm_uninstall.log" 2>&1 \
                && ok "npm package removed." \
                || warn "npm uninstall failed (see $LOG_DIR/npm_uninstall.log), cleaning up manually."
        fi
        local nroot; nroot="$(npm root -g 2>/dev/null)"
        [ -n "$nroot" ] && [ -d "$nroot/code-server" ] && rm -rf "$nroot/code-server"
    fi

    local p
    for p in "${CS_LOCATIONS[@]}"; do
        [ -e "$p" ] && { info "Removing: $p"; rm -rf "$p"; }
    done
    for p in "$HOME"/.local/lib/code-server-*; do
        [ -e "$p" ] && { info "Removing: $p"; rm -rf "$p"; }
    done
    rm -f "$PREFIX/bin/code-server" "$HOME/.local/bin/code-server" \
          "$HOME/.yarn/bin/code-server" \
          "$HOME/.config/yarn/global/node_modules/.bin/code-server" 2>/dev/null

    # Helper scripts from older versions of this installer, replaced by
    # ~/code-server.sh: removed so only one set of commands remains.
    rm -f "$PREFIX/bin/code-server-start" "$PREFIX/bin/code-server-stop" \
          "$PREFIX/bin/code-server-restart" "$PREFIX/bin/code-server-status" \
          "$PREFIX/bin/code-server-logs" \
          "$HOME/bin/code-server-start" "$HOME/bin/code-server-stop" \
          "$HOME/bin/code-server-restart" "$HOME/bin/code-server-status" \
          "$OLD_PREFS_FILE" 2>/dev/null

    hash -r 2>/dev/null || true
    if have code-server; then
        warn "A 'code-server' binary is still in the PATH: $(command -v code-server)"
        warn "It was not installed by a known method; it will be overridden if possible."
    else
        ok "No code-server installation left."
    fi
}

purge_user_data() {
    step "Deleting user data (--purge-data)"
    warn "This deletes: $CONFIG_DIR, $DATA_DIR (extensions, settings, password) and $WRAPPER_CONF."
    if ask_yes_no "Confirm PERMANENT deletion of this data?" no; then
        stop_running_instance
        rm -rf "$CONFIG_DIR" "$DATA_DIR" 2>/dev/null
        rm -f "$LOG_FILE" "$LOG_FILE.1" "$WRAPPER_CONF" "$WRAPPER_CONF.bak" 2>/dev/null
        ok "User data deleted."
    else
        info "Deletion cancelled, data kept."
        PURGE_DATA=0
    fi
}

# ---------------------------------------------------------------------------
# --uninstall mode
# ---------------------------------------------------------------------------
if [ "$UNINSTALL_ONLY" = "1" ]; then
    purge_code_server
    rm -f "$BOOT_FILE" "$WRAPPER" "$PID_FILE" 2>/dev/null
    have termux-wake-unlock && termux-wake-unlock >/dev/null 2>&1
    if ask_yes_no "Also delete $WRAPPER_CONF, the editor settings and the extensions?" no; then
        rm -f "$WRAPPER_CONF" "$WRAPPER_CONF.bak" "$LOG_FILE" "$LOG_FILE.1" 2>/dev/null
        rm -rf "$CONFIG_DIR" "$DATA_DIR" 2>/dev/null
        ok "Settings, configuration and data deleted."
    fi
    ok "Uninstall complete."
    exit 0
fi

wake_lock

# ---------------------------------------------------------------------------
# 1. Shared storage
# ---------------------------------------------------------------------------
if [ ! -d "$HOME/storage" ] && have termux-setup-storage; then
    info "Requesting access to shared storage (/sdcard) — accept the Android prompt if it appears."
    termux-setup-storage >/dev/null 2>&1 || warn "termux-setup-storage refused or failed, continuing."
    sleep 1
fi

# ---------------------------------------------------------------------------
# 2. Package update
# ---------------------------------------------------------------------------
if [ "$SKIP_UPDATE" = "1" ]; then
    info "Package update skipped (--skip-update)."
else
    step "Updating Termux packages"
    apt_repair
    if apt-get "${APT_OPTS[@]}" update >"$LOG_DIR/apt_update.log" 2>&1; then
        ok "Repositories updated."
    else
        warn "apt update failed (see $LOG_DIR/apt_update.log)."
        warn "The mirror may be unreachable: run 'termux-change-repo', then run this script again."
    fi
    if apt-get "${APT_OPTS[@]}" upgrade >"$LOG_DIR/apt_upgrade.log" 2>&1; then
        ok "Packages upgraded."
    else
        warn "apt upgrade failed (see $LOG_DIR/apt_upgrade.log), continuing."
    fi
fi

# ---------------------------------------------------------------------------
# 3. Dependencies
# ---------------------------------------------------------------------------
step "Dependencies"
# Required: Node.js LTS + the toolchain needed to build native npm modules.
DEPS_REQUIRED=(build-essential binutils pkg-config python nodejs-lts curl procps coreutils)
# Optional: useful but not blocking.
DEPS_OPTIONAL=(git ripgrep openssl)

if dpkg_installed nodejs && ! dpkg_installed nodejs-lts; then
    warn "The 'nodejs' package is installed. It conflicts with 'nodejs-lts' and will be REPLACED."
    warn "Other programs will then use the LTS version of Node.js."
fi

info "Installing: ${DEPS_REQUIRED[*]}"
if ! apt-get "${APT_OPTS[@]}" install "${DEPS_REQUIRED[@]}" >"$LOG_DIR/deps.log" 2>&1; then
    apt_repair
    apt-get "${APT_OPTS[@]}" install "${DEPS_REQUIRED[@]}" >"$LOG_DIR/deps.log" 2>&1 \
        || die "Failed to install the dependencies. See $LOG_DIR/deps.log"
fi
ok "Required dependencies installed."

: > "$LOG_DIR/deps_optional.log"
for pkg in "${DEPS_OPTIONAL[@]}"; do
    apt-get "${APT_OPTS[@]}" install "$pkg" >>"$LOG_DIR/deps_optional.log" 2>&1 \
        || warn "Optional package '$pkg' could not be installed (see $LOG_DIR/deps_optional.log)."
done

# Optional: libandroid-spawn fixes some native builds (posix_spawn).
if apt-get "${APT_OPTS[@]}" install libandroid-spawn >"$LOG_DIR/libandroid-spawn.log" 2>&1; then
    if [ -f "$PREFIX/lib/libandroid-spawn.so" ] || [ -f "$PREFIX/lib/libandroid-spawn.a" ]; then
        export LDFLAGS="${LDFLAGS:-} -landroid-spawn"
        info "libandroid-spawn available: LDFLAGS adjusted for native modules."
    fi
fi

have node || die "node not found after installing nodejs-lts."
have npm  || die "npm not found after installing nodejs-lts."

NODE_VERSION="$(node -v 2>/dev/null)"
NODE_MAJOR="$(printf '%s' "$NODE_VERSION" | sed 's/^v//; s/\..*//')"
info "node: $NODE_VERSION    npm: $(npm -v 2>/dev/null)"

npm config set python "$(command -v python3 || command -v python)" >/dev/null 2>&1 || true
npm_config_python="$(command -v python3 || command -v python)"
export npm_config_python

AVAIL_MB="$(df -Pm "$PREFIX" 2>/dev/null | awk 'NR==2 {print $4}')"
if is_uint "${AVAIL_MB:-}" && [ "$AVAIL_MB" -lt 1500 ]; then
    warn "Low free space: ${AVAIL_MB} MB. An npm install needs about 1.5 GB."
fi

# ---------------------------------------------------------------------------
# 4. Removal, then installation
# ---------------------------------------------------------------------------
[ "$PURGE_DATA" = "1" ] && purge_user_data
[ "$DO_RESET" = "1" ] && purge_code_server

install_via_tur() {
    info "TUR method (prebuilt package, fast)..."
    if ! apt-get "${APT_OPTS[@]}" install tur-repo >"$LOG_DIR/tur_repo.log" 2>&1; then
        warn "Could not enable the TUR repository (see $LOG_DIR/tur_repo.log)."
        return 1
    fi
    apt-get "${APT_OPTS[@]}" update >"$LOG_DIR/tur_update.log" 2>&1 || true
    if ! apt-get "${APT_OPTS[@]}" install --reinstall code-server >"$LOG_DIR/tur_install.log" 2>&1; then
        warn "The TUR 'code-server' package could not be installed (see $LOG_DIR/tur_install.log)."
        return 1
    fi
    ok "code-server installed from TUR."
    return 0
}

install_via_npm() {
    info "npm method (builds native modules such as argon2 and node-pty)."
    info "This takes several minutes on a phone. Keep Termux in the foreground."

    local rc=0
    local -a npm_env=()
    : > "$LOG_DIR/npm_install.log"

    npm install --global --no-fund --no-audit code-server >>"$LOG_DIR/npm_install.log" 2>&1 || rc=$?

    if [ $rc -ne 0 ] && grep -qi "requires node\|FORCE_NODE_VERSION\|Unsupported engine" "$LOG_DIR/npm_install.log"; then
        warn "code-server rejects Node.js $NODE_VERSION. Retrying with FORCE_NODE_VERSION=$NODE_MAJOR."
        warn "Not officially supported: unexpected behaviour is possible."
        npm_env=(FORCE_NODE_VERSION="$NODE_MAJOR")
        rc=0
        env "${npm_env[@]}" npm install --global --no-fund --no-audit code-server \
            >>"$LOG_DIR/npm_install.log" 2>&1 || rc=$?
    fi

    if [ $rc -ne 0 ]; then
        warn "npm failed. Cleaning the npm cache and retrying..."
        npm cache clean --force >/dev/null 2>&1 || true
        rm -rf "$PREFIX/lib/node_modules/code-server" 2>/dev/null
        rc=0
        env "${npm_env[@]}" npm install --global --no-fund --no-audit code-server \
            >>"$LOG_DIR/npm_install.log" 2>&1 || rc=$?
    fi

    if [ $rc -ne 0 ]; then
        warn "npm install failed (see $LOG_DIR/npm_install.log):"
        tail -n 15 "$LOG_DIR/npm_install.log" | sed 's/^/    /'
        return 1
    fi
    ok "code-server installed with npm."
    return 0
}

step "Installing code-server"
INSTALL_METHOD=""

try_method() {
    local m="$1"
    case "$m" in
        tur) install_via_tur || return 1 ;;
        npm) install_via_npm || return 1 ;;
    esac
    info "Checking the installation ($m)..."
    if cs_health_check; then
        ok "Working $m install: $CS_VERSION"
        INSTALL_METHOD="$m"
        return 0
    fi
    warn "BROKEN $m install: $CS_HEALTH_MSG"
    return 1
}

if [ "$DO_RESET" = "0" ] && have code-server && cs_health_check; then
    ok "Existing install works: $CS_VERSION (--no-reset)"
    INSTALL_METHOD="existing"
else
    case "$METHOD" in
        tur)  try_method tur || die "TUR install failed or is broken. Try again with --method npm." ;;
        npm)  try_method npm || die "npm install failed or is broken. See $LOG_DIR/npm_install.log" ;;
        auto)
            if ! try_method tur; then
                warn "Switching to the npm method."
                purge_code_server
                try_method npm || die "Both methods failed. Logs in $LOG_DIR"
            fi
            ;;
    esac
fi

CS_BIN="$(command -v code-server)"
CS_ROOT="$(cs_install_root || true)"
info "Binary: $CS_BIN"
[ -n "$CS_ROOT" ] && info "Install directory: $CS_ROOT"

# ---------------------------------------------------------------------------
# 5. argon2 native module (used for password authentication)
# ---------------------------------------------------------------------------
if [ -n "$CS_ROOT" ]; then
    ARGON2_DIR=""
    for d in "$CS_ROOT/node_modules/argon2" "$CS_ROOT/lib/vscode/node_modules/argon2"; do
        [ -d "$d" ] && { ARGON2_DIR="$d"; break; }
    done
    if [ -n "$ARGON2_DIR" ]; then
        if find "$ARGON2_DIR" -name "*.node" 2>/dev/null | grep -q .; then
            ok "argon2 native module present."
        else
            warn "argon2 native binary missing: rebuilding for $ARCH..."
            ( cd "$CS_ROOT" && npm rebuild argon2 ) >"$LOG_DIR/argon2_build.log" 2>&1 \
                || ( cd "$ARGON2_DIR" && npx --yes node-gyp rebuild ) >>"$LOG_DIR/argon2_build.log" 2>&1
            if find "$ARGON2_DIR" -name "*.node" 2>/dev/null | grep -q .; then
                ok "argon2 rebuilt."
            else
                warn "argon2 rebuild failed (see $LOG_DIR/argon2_build.log)."
                warn "Password authentication may not work; CS_AUTH=none remains usable."
            fi
        fi
    else
        info "No argon2 directory found (self-contained build): nothing to do."
    fi
fi

# ---------------------------------------------------------------------------
# 6. ripgrep fix (powers "search in files" in the editor)
#    The bundled rg binary is built for desktop Linux; Termux's own rg is
#    linked in its place.
# ---------------------------------------------------------------------------
step "ripgrep fix"
RG_BIN="$(command -v rg 2>/dev/null)"
if [ -z "$RG_BIN" ]; then
    warn "rg not found: searching inside files will not work."
elif [ -z "$CS_ROOT" ]; then
    warn "Install directory unknown: ripgrep fix skipped."
else
    RG_PATCHED=0
    while IFS= read -r rg_dir; do
        [ -n "$rg_dir" ] || continue
        mkdir -p "$rg_dir/bin" 2>/dev/null
        ln -sfn "$RG_BIN" "$rg_dir/bin/rg" && RG_PATCHED=$((RG_PATCHED+1))
    done < <(find "$CS_ROOT" -type d \( -path "*node_modules/@vscode/ripgrep" -o -path "*node_modules/vscode-ripgrep" \) 2>/dev/null)
    if [ "$RG_PATCHED" -gt 0 ]; then
        ok "Termux ripgrep linked in $RG_PATCHED location(s)."
    else
        info "No bundled ripgrep found (build already uses the system rg): nothing to do."
    fi
fi

# ---------------------------------------------------------------------------
# Previous launcher settings (reused as defaults: a reinstall must not
# silently change the user's choices)
# ---------------------------------------------------------------------------
PREV_CONF=0
if [ -f "$WRAPPER_CONF" ]; then
    if bash -n "$WRAPPER_CONF" 2>/dev/null; then
        PREV_CONF=1
        info "Previous settings found: $WRAPPER_CONF"
    else
        warn "$WRAPPER_CONF contains a syntax error: saved as $WRAPPER_CONF.bak, defaults used."
        mv -f "$WRAPPER_CONF" "$WRAPPER_CONF.bak" 2>/dev/null
    fi
fi

# Reads one variable from the previous settings file, in a subshell so it
# cannot overwrite this script's own variables.
conf_get() {
    [ "$PREV_CONF" = "1" ] || return 0
    ( set +u; . "$WRAPPER_CONF" >/dev/null 2>&1 </dev/null; printf '%s' "${!1:-}" )
}
prev_or()     { local v; v="$(conf_get "$1")"; if [ -n "$v" ]; then printf '%s' "$v"; else printf '%s' "$2"; fi; }
prev_answer() { if [ "$(conf_get "$1")" = "1" ]; then echo yes; else echo no; fi; }

# ---------------------------------------------------------------------------
# 7. Root access + inotify limit
#    The editor watches files with inotify; large projects can exceed
#    Android's default limit (ENOSPC errors). Raising it requires root.
# ---------------------------------------------------------------------------
step "Advanced options"
IS_ROOT_USER=0; [ "$(id -u)" = "0" ] && IS_ROOT_USER=1
ROOT_HELPER="$(find_real_su || true)"
USE_ROOT_INOTIFY=0
INOTIFY_WATCHES="$(prev_or CS_INOTIFY_WATCHES 524288)"
is_uint "$INOTIFY_WATCHES" || INOTIFY_WATCHES=524288

if [ "$IS_ROOT_USER" = "1" ] || [ -n "$ROOT_HELPER" ]; then
    if [ "$IS_ROOT_USER" = "1" ]; then
        info "This shell already runs as root (uid 0)."
    else
        info "su binary found: $ROOT_HELPER"
    fi
    CURRENT_LIMIT="$(cat /proc/sys/fs/inotify/max_user_watches 2>/dev/null || echo unknown)"
    info "Current inotify limit: $CURRENT_LIMIT"
    if ask_yes_no "Raise the inotify limit to $INOTIFY_WATCHES (avoids ENOSPC errors on large projects)?" "$(prev_answer CS_ROOT_INOTIFY)"; then
        if [ "$IS_ROOT_USER" = "1" ]; then
            if echo "$INOTIFY_WATCHES" > /proc/sys/fs/inotify/max_user_watches 2>"$LOG_DIR/inotify.log"; then
                USE_ROOT_INOTIFY=1; ok "inotify limit set to $INOTIFY_WATCHES."
            else
                warn "Direct write refused (see $LOG_DIR/inotify.log)."
            fi
        else
            warn "A root permission prompt will appear: accept it."
            if "$ROOT_HELPER" -c "echo $INOTIFY_WATCHES > /proc/sys/fs/inotify/max_user_watches" >"$LOG_DIR/inotify.log" 2>&1; then
                USE_ROOT_INOTIFY=1; ok "inotify limit set to $INOTIFY_WATCHES until the next reboot."
            else
                warn "Failed through $ROOT_HELPER (see $LOG_DIR/inotify.log). Root denied?"
            fi
        fi
    fi
else
    info "No root access detected: inotify tuning skipped (not required)."
fi

# ---------------------------------------------------------------------------
# 8. "Android as Linux" workaround (documented by Coder)
# ---------------------------------------------------------------------------
# ---------------------------------------------------------------------------
# 7b. Claude Code extension compatibility
#     The extension ships a native binary built for desktop Linux (glibc).
#     Android (Bionic) has no glibc loader, so the binary cannot start
#     ("the file is there, but a program it needs is missing").
#     Fix: the glibc loader from glibc-runner (Termux glibc repository) runs it.
#     The extension starts the binary directly in several places, so the
#     binary itself is renamed claude.real and replaced by a launcher script
#     (see claude-wrap-binary.sh, kept up to date while code-server runs).
#     This needs the "Android as Linux" workaround so that the extension
#     (linux-arm64 build) can be installed at all.
# ---------------------------------------------------------------------------
CLAUDE_COMPAT=0
echo
warn "Claude Code extension support (runs its Linux binary through glibc-runner)."
echo "   Adds the Termux glibc repository + glibc-runner (~100-200 MB) and a"
echo "   launcher wrapper. Forces the \"Android as Linux\" workaround below."
if [ "$CLAUDE_OPT" = "1" ]; then
    CLAUDE_COMPAT=1; info "--claude-code: enabled."
elif [ "$CLAUDE_OPT" = "0" ]; then
    info "--no-claude-code: skipped."
elif ask_yes_no "Set up Claude Code support?" "$(prev_answer CS_CLAUDE_COMPAT)"; then
    CLAUDE_COMPAT=1
fi

claude_find_binaries() {
    find "$DATA_DIR/extensions" -path '*anthropic.claude-code-*/resources/native-binary/claude' 2>/dev/null
}

setup_claude_support() {
    local loader b out rc found=0 bad=0

    case "$ARCH" in
        aarch64|arm64) ;;
        *) warn "glibc-runner only exists for aarch64: Claude Code support skipped."; return 1 ;;
    esac

    info "Enabling the Termux glibc repository..."
    apt-get "${APT_OPTS[@]}" install glibc-repo >"$LOG_DIR/glibc_repo.log" 2>&1 \
        || { apt_repair; apt-get "${APT_OPTS[@]}" install glibc-repo >"$LOG_DIR/glibc_repo.log" 2>&1; } \
        || { warn "glibc-repo failed (see $LOG_DIR/glibc_repo.log)."; return 1; }
    apt-get "${APT_OPTS[@]}" update >"$LOG_DIR/glibc_update.log" 2>&1 || true

    info "Installing glibc-runner..."
    apt-get "${APT_OPTS[@]}" install glibc-runner >"$LOG_DIR/glibc_runner.log" 2>&1 \
        || { apt_repair; apt-get "${APT_OPTS[@]}" install glibc-runner >"$LOG_DIR/glibc_runner.log" 2>&1; } \
        || { warn "glibc-runner failed (see $LOG_DIR/glibc_runner.log)."; return 1; }
    # Best effort: loader for musl-linked builds of Claude Code.
    apt-get "${APT_OPTS[@]}" install musl >"$LOG_DIR/musl.log" 2>&1 || true
    hash -r 2>/dev/null || true
    have grun || { warn "'grun' not found after installing glibc-runner."; return 1; }

    loader="$(ls "$PREFIX"/glibc/lib/ld-linux-aarch64.so.1 2>/dev/null | head -n1)"
    if [ -n "$loader" ] && ! "$loader" --version >"$LOG_DIR/glibc_loader.log" 2>&1; then
        warn "The glibc loader does not run (see $LOG_DIR/glibc_loader.log)."
        return 1
    fi
    ok "glibc-runner ready: $(command -v grun)"

    mkdir -p "$CONFIG_DIR" || return 1

    # ---- Library that fixes /proc/self/exe --------------------------------
    # Claude Code's binary is a Bun "standalone" executable: it re-reads its
    # own file to find its embedded code. Started through the glibc loader
    # (as Android requires), /proc/self/exe is the LOADER, and older Bun
    # versions then behave like plain `bun` (they print Bun's help instead of
    # running Claude Code). This tiny library makes /proc/self/exe point to
    # the real file. It is harmless for newer Bun versions.
    SELFEXE_SO="$CONFIG_DIR/claude-selfexe.so"
    rm -f "$SELFEXE_SO"
embed_claude_selfexe_c() {
    cat <<'TPF_EOF_CA021E7EA9C5'
/* claude-selfexe.c — LD_PRELOAD helper: makes /proc/self/exe point to $CT_REAL_EXE.
 * Needed when a program is started as "ld.so program" (the only way to run a
 * glibc program on Android): /proc/self/exe is then the loader, and programs
 * that read themselves (Bun standalone executables) cannot find their
 * embedded code. No headers are used, so it builds without a glibc sysroot. */
#ifndef SYS_READLINKAT
#define SYS_READLINKAT 78   /* aarch64 */
#endif
#ifndef SYS_OPENAT
#define SYS_OPENAT 56       /* aarch64 */
#endif
#define AT_FDCWD_ (-100)

extern long syscall(long number, ...);
extern char *getenv(const char *name);

static int is_self(const char *p)
{
    static const char s[] = "/proc/self/exe";
    int i = 0;
    if (!p) return 0;
    while (s[i] && p[i] == s[i]) i++;
    return s[i] == 0 && p[i] == 0;
}
static const char *real(void) { return getenv("CT_REAL_EXE"); }

long readlinkat(int dirfd, const char *path, char *buf, unsigned long size)
{
    const char *r = real();
    if (r && is_self(path)) {
        unsigned long n = 0;
        while (r[n] && n < size) { buf[n] = r[n]; n++; }
        return (long)n;
    }
    return syscall(SYS_READLINKAT, (long)dirfd, (long)path, (long)buf, (long)size);
}
long readlink(const char *path, char *buf, unsigned long size) { return readlinkat(AT_FDCWD_, path, buf, size); }

int openat(int dirfd, const char *path, int flags, ...)
{
    const char *r = real();
    __builtin_va_list ap; unsigned int mode;
    __builtin_va_start(ap, flags); mode = __builtin_va_arg(ap, unsigned int); __builtin_va_end(ap);
    if (r && is_self(path)) path = r;
    return (int)syscall(SYS_OPENAT, (long)dirfd, (long)path, (long)flags, (long)mode);
}
