    fi
    for pid in $(pgrep -f "$CS_PROC_PATTERN" 2>/dev/null); do
        [ "$pid" = "$$" ] && continue
        [ "$pid" = "${PPID:-0}" ] && continue
        is_cs_pid "$pid" && { echo "$pid"; return 0; }
    done
    return 1
}

pid_tree() {
    local p
    echo "$1"
    for p in $(pgrep -P "$1" 2>/dev/null); do pid_tree "$p"; done
}

stop_pid() {
    local pids p i alive=""
    pids="$(pid_tree "$1")"
